<?php
namespace App\Http\Controllers; use App\Models\{DeliveryTask,DeliveryStatusHistory,Reservation}; use Illuminate\Http\Request;
class DeliveryController extends Controller { public function index(){ $q=DeliveryTask::with('reservation'); if(auth()->user()->role==='VOLUNTEER') $q->where('volunteer_id',auth()->user()->partnerProfile->profile_id); return view('deliveries.index',['deliveries'=>$q->get()]);} public function createFromReservation(Request $r, Reservation $reservation){$task=DeliveryTask::create(['reservation_id'=>$reservation->reservation_id,'volunteer_id'=>auth()->user()->partnerProfile->profile_id,'pickup_address'=>$reservation->donation->pickup_address,'delivery_address'=>$reservation->request->charity->address ?? 'Charity address']); return redirect('/deliveries/'.$task->delivery_id.'/edit');} public function edit(DeliveryTask $delivery){return view('deliveries.edit',compact('delivery'));} public function update(Request $r, DeliveryTask $delivery){$old=$delivery->delivery_status; $status=$r->validate(['delivery_status'=>'required|in:ASSIGNED,PICKED_UP,DELIVERED,CANCELLED','remarks'=>'nullable']); $extra=$status['delivery_status']==='PICKED_UP'?['picked_up_at'=>now()]:($status['delivery_status']==='DELIVERED'?['delivered_at'=>now()]:[]); $delivery->update(['delivery_status'=>$status['delivery_status']]+$extra); DeliveryStatusHistory::create(['delivery_id'=>$delivery->delivery_id,'old_status'=>$old,'new_status'=>$status['delivery_status'],'changed_by'=>auth()->id(),'remarks'=>$status['remarks']??null]); return back();} }
